INSERT INTO `movies` VALUES (39, '独领风骚', '喜剧,爱情', 1995, '艾米·海克林', '肤浅、富有且在社交上非常成功的雪儿是她所在的比佛利山庄高中的风云人物。自认为是个媒人，雪儿首先撮合了两位老师约会。', 'https://www.imdb.com/title/tt0112697/mediaviewer/rm2643037953/?ref_=tt_ov_i', '艾丽西亚·西尔维斯通,史黛西·达什,布兰妮·墨菲', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (47, '七宗罪', '悬疑,惊悚', 1995, '大卫·芬奇', '一名新手侦探和一名资深侦探追捕一名以七宗罪为动机的连环杀手。', 'https://m.media-amazon.com/images/M/MV5BY2IzNzMxZjctZjUxZi00YzAxLTk3ZjMtODFjODdhMDU5NDM1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '摩根·弗里曼, 安德鲁·凯文·沃克, 丹尼尔·扎卡帕, 布拉德·皮特, 格温妮丝·帕特洛, 约翰·卡西尼', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (48, '风中奇缘', '动画,儿童,剧情,音乐,爱情', 1995, '迈克·加布里尔', '当英国殖民者入侵17世纪的弗吉尼亚时，一名英国士兵和一位阿尔冈昆首领的女儿展开了一段浪漫故事。', 'https://m.media-amazon.com/images/M/MV5BY2ZlNTUxM2MtYmJhYS00Y2E5LTlmYTItZDhlNWJmMmRiYTYzXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '乔·贝克, 克里斯蒂安·贝尔, 艾琳·贝达, 比利·康诺利, 詹姆斯·阿帕穆特·法尔, 梅尔·吉布森', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (50, '非常嫌疑犯', '犯罪,悬疑,惊悚', 1995, '布莱恩·辛格', '码头枪击事件的唯一幸存者讲述了臭名昭著的罪犯凯撒·苏斯如何影响事件发展的故事，这一切始于五名罪犯在一次看似随机的警方列队辨认中相遇。', 'https://m.media-amazon.com/images/M/MV5BOTE5MDUxZDUtZWZmZC00NDVmLWFhOGQtNWI2YTc4NzY3MGQ0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '史蒂芬·鲍德温, 加布里埃尔·伯恩, 本尼西奥·德尔·托罗, 凯文·波拉克, 凯文·史派西, 查兹·帕尔明特瑞', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (60, '魔柜小奇兵', '冒险,儿童,奇幻', 1995, '弗兰克·奥兹', '在布鲁克林长大的男孩奥米在生日时收到了一些奇怪的礼物：哥哥送的一个木制柜子，妈妈送的一套古董钥匙，以及最好的朋友帕特里克送的一个塑料印第安小人。', 'https://m.media-amazon.com/images/M/MV5BNmIzNTIzYTEtYWM5Zi00NmRiLTk4NzYtYTRiZmI0OWZkYjBhXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '哈尔·斯卡迪诺, 利特福特, 琳赛·克洛斯, 理查德·詹金斯, 里希·巴特, 史蒂夫·库根', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (62, '生命因你动听', '剧情', 1995, '斯蒂芬·赫瑞克', '一位沮丧的作曲家在一名高中音乐老师身上找到了满足感。', 'https://m.media-amazon.com/images/M/MV5BZGJkOTFkYjEtNzg5Zi00NWIyLTkyN2QtMDExNjk1NTg1NTQ1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '理查德·德莱福斯, 格伦妮·海德利, 杰·托马斯, 奥林匹亚·杜卡基斯, 威廉姆·H·梅西, 艾丽西亚·维特', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (69, '星期五', '喜剧', 1995, 'F·加里·格雷', '今天是星期五，克雷格和斯莫基必须凑齐他们欠当地恶霸的200美元，否则星期六就不好过了。', 'https://m.media-amazon.com/images/M/MV5BMWI3MmM2MTItN2MxZS00Y2NhLWE5ZWEtMzU3YWNiNmU3NmFmXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '艾斯·库珀, 克里斯·塔克, 妮娅·朗, 托米·利斯特 Jr., 约翰·威瑟斯庞, 安娜·玛丽亚·霍斯福德', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (70, '杀出个黎明', '动作,喜剧,恐怖,惊悚', 1996, '罗伯特·罗德里格兹', '两名罪犯和他们的人质不知不觉中在一个人满为患的吸血鬼卡车停靠站寻求临时庇护，结果一片混乱。', 'https://m.media-amazon.com/images/M/MV5BZGNjMWMwNWEtYTQ2YS00N2E5LTg5ZWYtMDgzM2UxMTE1ZTE4XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '乔治·克鲁尼, 昆汀·塔伦蒂诺, 哈威·凯特尔, 朱丽叶特·刘易斯, 欧内斯特·刘, 萨尔玛·海耶克', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (95, '断箭', '动作,冒险,惊悚', 1996, '吴宇森', '恐怖分子从美国军方偷走了核弹头，但他们没料到一名飞行员和一名公园护林员会破坏他们的计划。', 'https://m.media-amazon.com/images/M/MV5BMjkxMzA5ZWMtZWU0MS00MTBhLWFjNzItYWI2ZGU4YjE2MTc4XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '约翰·特拉沃尔塔, 克里斯蒂安·斯莱特, 萨曼莎·玛西斯, 德尔罗伊·林多, 鲍勃·冈顿, 弗兰克·威利', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (104, '球场古惑仔', '喜剧', 1996, '丹尼斯·杜根', '在他的祖母的房子被国税局没收后，一个脾气暴躁的曲棍球运动员发挥自己的天赋去打高尔夫，以赚大钱赎回祖母的房子。', 'https://m.media-amazon.com/images/M/MV5BMzMyZTM1MTMtNDdjOS00NzIzLTkxY2QtZTU4OGYxOTUwNDMxXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '亚当·桑德勒, 克里斯托弗·麦克唐纳, 朱丽·鲍温, 弗朗西斯·贝, 卡尔·韦瑟斯, 艾伦·科瓦特', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (110, '勇敢的心', '动作,剧情,战争', 1995, '梅尔·吉布森', '苏格兰勇士威廉·华莱士带领同胞们反抗，以从英格兰国王爱德华一世的暴政中解放他的家园。', 'https://m.media-amazon.com/images/M/MV5BNGMxZDBhNGQtYTZlNi00N2UzLWI4NDEtNmUzNWM2NTdmZDA0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '詹姆斯·罗宾逊, 肖恩·劳勒, 桑迪·尼尔森, 詹姆斯·卡沙莫, 肖恩·麦金利, 艾伦·塔尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (111, '出租车司机', '犯罪,剧情,惊悚', 1976, '马丁·斯科塞斯', '一名精神不稳定的越战老兵在纽约市开夜班出租车，他所看到的颓废和肮脏助长了他对暴力行为的冲动。', 'https://m.media-amazon.com/images/M/MV5BZDNhMGYwM2UtMTdlZS00MGQ1LWI2YzAtODY5YWI1MjYyNzRmXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '迪亚汉·阿博特, 弗兰克·阿杜, 维克托·阿尔戈, 吉诺·阿尔迪托, 加思·埃弗里, 彼得·博伊尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (112, '红番区', '动作,冒险,喜剧,犯罪', 1995, '唐季礼', '一位到纽约探望并帮助叔叔的年轻人发现自己被迫用他的武术技能与街头帮派和黑手党斗争。', 'https://m.media-amazon.com/images/M/MV5BNWUxMDcyZTMtYzJjMi00Y2Q1LWE3NWMtNTRiNGQxZTljYjE2XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '成龙, 梅艳芳, 叶芳华, 董骠, 马克·阿克斯特罗姆, 加文·克罗斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (123, '重庆森林', '剧情,悬疑,爱情', 1994, '王家卫', '两名忧郁的香港警察坠入爱河：一个爱上了神秘的黑道女性人物，另一个爱上了他常去的深夜餐厅里一位美丽脱俗的女招待。', 'https://m.media-amazon.com/images/M/MV5BNDQ4ZmYxODctZDVlZC00OTcxLWJjOGItZjRlMzk4MDA1Yjg1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '林青霞, 梁朝伟, 王菲, 金城武, 周嘉玲, 陈辉虹', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (141, '假凤虚凰', '喜剧', 1996, '迈克·尼科尔斯', '一对同性恋歌舞俱乐部老板和他的变装皇后伴侣同意装出一副异性恋表象，以便他们的儿子能把他介绍给未婚妻的右翼保守派父母。', 'https://m.media-amazon.com/images/M/MV5BMTM2NjExODYyOF5BMl5BanBnXkFtZTcwNTc0NjgyNA@@._V1_FMjpg_UX1000_.jpg', '罗宾·威廉姆斯, 吉恩·哈克曼, 内森·连恩, 黛安娜·韦斯特, 丹·福特曼, 卡莉斯塔·弗洛克哈特', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (145, '绝地战警', '动作,喜剧,犯罪,剧情,惊悚', 1995, '迈克尔·贝', '两名时髦的侦探在调查一起从他们警察分局证物室被盗的海洛因案件时，保护一名谋杀案目击者。', 'https://m.media-amazon.com/images/M/MV5BMWNjZWEwNDMtMWE1ZC00MTgwLTk2YzAtYmE0NTkwOWVhMDI0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '丽莎·博伊尔, 迈克尔·塔利菲罗, 伊曼纽尔·克西里布, 切基·卡尤, 马克·麦考利, 拉尔夫·冈萨雷斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (150, '阿波罗13号', '冒险,剧情,IMAX', 1995, '朗·霍华德', '阿波罗13号飞船遭受巨大内部损坏，将船上三名宇航员的生命置于危险之中，美国宇航局必须制定战略将其安全送回地球。', 'https://m.media-amazon.com/images/M/MV5BMGZmNGY1OTAtNjFkYS00MjcyLWFlZjUtYzEyMDllZGZhMzM3XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '汤姆·汉克斯, 比尔·帕克斯顿, 凯文·贝肯, 加里·西尼斯, 埃德·哈里斯, 凯瑟琳·昆兰', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (153, '永远的蝙蝠侠', '动作,冒险,喜剧,犯罪', 1995, '乔·舒马赫', '蝙蝠侠必须与前地方检察官哈维·丹特（现为双面人）和爱德华·尼格玛（谜语人）战斗，并得到一位多情的心理学家和一位年轻的马戏团杂技演员的帮助，后者成为了他的搭档罗宾。', 'https://m.media-amazon.com/images/M/MV5BMTUyNjJhZWItMTZkNS00NDc4LTllNjUtYTg3NjczMzA5ZTViXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '方·基默, 汤米·李·琼斯, 金·凯瑞, 妮可·基德曼, 克里斯·奥唐纳, 迈克尔·高夫', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (160, '刚果惊魂', '动作,冒险,悬疑,科幻', 1995, '弗兰克·马歇尔', '当一支前往非洲刚果的探险队以灾难告终时，一个新的团队被召集起来调查出了什么问题。', 'https://m.media-amazon.com/images/M/MV5BOTc0MmM1MmMtYTI0Yi00YzJlLTg4MjctNjBlOGQ4NGJjZTNmXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '劳拉·琳妮, 迪伦·沃尔什, 厄尼·哈德森, 蒂姆·克里, 格兰特·赫斯洛夫, 乔·唐·贝克', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (161, '红潮风暴', '剧情,惊悚,战争', 1995, '托尼·斯科特', '在一艘美国核导弹潜艇上，一名年轻的大副发动兵变，阻止他好战的舰长在确认发射命令前发射导弹。', 'https://m.media-amazon.com/images/M/MV5BNTNhZDk2NmQtNDc3ZC00Nzk3LWFmNTctYTc0OWMyNGM0ZWYyXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '丹泽尔·华盛顿, 吉恩·哈克曼, 马特·克拉文, 乔治·真达, 维果·莫腾森, 詹姆斯·甘多菲尼', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (163, '杀人三部曲', '动作,爱情,西部', 1995, '罗伯特·罗德里格兹', '前音乐家和枪手埃尔·马里亚奇在离开很久之后来到了一个墨西哥边境小镇。他的过去很快找上门来，他很快就被卷入了当地毒枭布乔和他的帮派的纷争中。', 'https://m.media-amazon.com/images/M/MV5BN2IzOThmNTMtODE4My00NTI1LThkOWMtNTA4MTc4NWI1NTNlXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '安东尼奥·班德拉斯, 萨尔玛·海耶克, 华金·德·阿尔梅达, 切奇·马林, 史蒂夫·布西密, 卡洛斯·戈麦斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (165, '虎胆龙威3：纽约大劫案', '动作,犯罪,惊悚', 1995, '约翰·麦克蒂尔南', '约翰·麦克莱恩被迫暂停职务，与一名恐怖分子玩“西蒙说”的游戏，这名恐怖分子在纽约市周围安放了炸弹，如果麦克莱恩不照他说的做就会引爆。', 'https://m.media-amazon.com/images/M/MV5BYjkzNzdkMTctNzMwMS00M2Q0LWIyOTMtODFjODdhMDU5NDM1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '布鲁斯·威利斯, 杰瑞米·艾恩斯, 塞缪尔·杰克逊, 格雷厄姆·格林, 科琳·坎普, 拉里·布里格曼', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (170, '黑客', '动作,冒险,犯罪,惊悚', 1995, '伊恩·索夫特利', '青少年黑客发现了一个犯罪阴谋，计划使用一种计算机病毒来倾覆五艘油轮。', 'https://m.media-amazon.com/images/M/MV5BOGZkZTc2ZjItNzIzMS00ODRlLTliNjgtZjRmNzM2NjkzZTU1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '约翰尼·李·米勒, 安吉丽娜·朱莉, 杰西·布拉德福德, 马修·里沃德, 劳伦斯·梅森, 雷诺利·圣地亚哥', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (180, '商场老鼠', '喜剧,爱情', 1995, '凯文·史密斯', '两个最好的朋友都被女友甩了，在当地商场寻求庇护。', 'https://m.media-amazon.com/images/M/MV5BZDM2MWVkMWItNjhjMy00MDUzLWEyOTAtN2I0MzNlZjc4Mjk0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '莎侬·多赫提, 杰里米·伦敦, 杰森·李, 克莱尔·弗兰妮, 本·阿弗莱克, 乔伊·劳伦·亚当斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (185, '网络惊魂', '动作,犯罪,惊悚', 1995, '欧文·温克勒', '当计算机程序员安吉拉·贝内特无意中发现政府机密时，她发现自己被一个未知的敌人追捕，这个敌人一心要彻底摧毁她。', 'https://m.media-amazon.com/images/M/MV5BMDNhMjgxODUtMWRjOS00N2JlLWEyYWEtOWJhNWQ1MTdmYTllXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '桑德拉·布洛克, 杰瑞米·诺森, 丹尼斯·米勒, 黛安·贝克, 温迪·加泽尔, 肯·霍华德', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (196, '异种', '恐怖,科幻', 1995, '罗杰·唐纳森', '一组科学家试图追捕并诱捕一个致命的外星女妖，阻止她成功与人类交配。', 'https://m.media-amazon.com/images/M/MV5BMjEzOTkxNTcyM15BMl5BanBnXkFtZTcwOTk0MjI3NA@@._V1_FMjpg_UX1000_.jpg', '本·金斯利, 迈克尔·马德森, 阿尔弗雷德·莫里纳, 福里斯特·惠特克, 玛格·海根柏格, 娜塔莎·金斯基', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (208, '未来水世界', '动作,冒险,科幻', 1995, '凯文·雷诺兹', '在两极冰盖融化、地球几乎完全被淹没的未来，一位变异水手与饥饿和非法的“吸烟者”作斗争，并勉强帮助一名妇女和一个小女孩寻找干燥的陆地。', 'https://m.media-amazon.com/images/M/MV5BMjI5ZmQ3NTAtNWVhMi00ZmI2LTg3YTMtN2Q1MmNjYzMwZGI1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '凯文·科斯特纳, 凯姆·杰拉菲, 里克·阿维莱斯, R·D·考尔, 齐托·卡赞, 莱昂纳多·西米诺', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (215, '爱在黎明破晓前', '剧情,爱情', 1995, '理查德·林克莱特', '一位年轻男子和一位年轻女子在欧洲的火车上相遇，最终在维也纳共度了一个夜晚。不幸的是，两人都知道这可能只是他们唯一的一夜。', 'https://m.media-amazon.com/images/M/MV5BZDZhZmI1ZTUtYWI3NC00NTMwLTk3NWMtNDc0OGNjM2I0ZjlmXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '伊桑·霍克, 朱莉·德尔佩, 安德莉亚·埃克特, 汉诺·波西尔, 卡尔·布鲁克斯瓦格, 特克斯·鲁宾诺维茨', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (223, '疯狂店员', '喜剧', 1994, '凯文·史密斯', '讲述便利店店员丹特和兰德尔一天的生活，他们惹恼顾客，讨论电影，在商店屋顶上打曲棍球。', 'https://m.media-amazon.com/images/M/MV5BYzcwZTU5NzMtMGIxYi00NjRhLThkYTItNjhlYWQ0MjdhYWFmXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '布莱恩·奥哈罗兰, 杰夫·安德森, 玛丽莲·吉廖蒂, 丽莎·斯普纳, 杰森·缪斯, 凯文·史密斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (231, '阿呆与阿瓜', '冒险,喜剧', 1994, '彼得·法拉利', '一位女士将一个公文包遗忘在机场航站楼后，一个笨拙的豪华轿车司机和他更笨的朋友踏上了前往阿斯彭的爆笑跨国公路旅行，以便归还公文包。', 'https://m.media-amazon.com/images/M/MV5BNGQxZDA1MmMtYWQ1Ni00NTJmLTljMjgtZWVmODllODVhMzgyXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '金·凯瑞, 杰夫·丹尼尔斯, 劳伦·霍利, 迈克·斯塔尔, 凯伦·达菲, 查尔斯·罗基特', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (235, '艾德·伍德', '喜剧,剧情', 1994, '蒂姆·波顿', '有野心但麻烦不断的电影导演爱德华·D·伍德 Jr. 尽其所能地实现他的梦想，尽管他缺乏才华。', 'https://m.media-amazon.com/images/M/MV5BOWU4NzlkZGEtODNmYi00YTVhLWIzYjAtZjBkN2Q1Y2U5NjE4XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '约翰尼·德普, 马丁·兰道, 莎拉·杰茜卡·帕克, 帕特丽夏·阿奎特, 杰弗瑞·琼斯, G·D·斯普拉德林', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (236, '情定巴黎', '动作,喜剧,爱情', 1995, '劳伦斯·卡斯丹', '一名女子飞往法国质问不忠的未婚夫，结果当她旁边座位上的迷人小偷利用她走私时，她陷入了麻烦。', 'https://m.media-amazon.com/images/M/MV5BMTkzMjg5MDQ3M15BMl5BanBnXkFtZTgwOTM5NTE0MDE@._V1_FMjpg_UX1000_.jpg', '梅格·瑞恩, 凯文·克莱恩, 蒂莫西·赫顿, 让·雷诺, 弗朗索瓦·克鲁塞, 苏珊·安贝', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (252, 'IQ情缘', '喜剧,爱情', 1994, '弗雷德·谢皮西', '一位机械师在物理学家阿尔伯特·爱因斯坦及其朋友的帮助下，追求爱因斯坦的数学家侄女。', 'https://m.media-amazon.com/images/M/MV5BMDkyZmFiNmQtNWY1YS00N2MxLWJkMDItNWI5ODIxNWY1M2FiXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '蒂姆·罗宾斯, 梅格·瑞恩, 沃尔特·马修, 卢·雅各比, 吉恩·萨克斯, 约瑟夫·马厄', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (253, '夜访吸血鬼', '剧情,恐怖', 1994, '尼尔·乔丹', '一个吸血鬼讲述了他史诗般的人生故事：爱情、背叛、孤独和饥渴。', 'https://m.media-amazon.com/images/M/MV5BYzJlN2NiZDQtZmI4NC00ZWFiLWFmMTUtMWM4ODVlOGFlODY1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '布拉德·皮特, 克里斯蒂安·斯莱特, 弗吉尼亚·麦科勒姆, 约翰·麦康奈尔, 汤姆·克鲁斯, 迈克·西利格', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (260, '星球大战4：新希望', '动作,冒险,科幻', 1977, '乔治·卢卡斯', '卢克·天行者与一位绝地武士、一位自大的飞行员、一位伍基人和两个机器人联手，从帝国的星球毁灭战斗站中拯救银河系，同时试图从神秘的达斯·维达手中解救莱娅公主。', 'https://m.media-amazon.com/images/M/MV5BOGUwMDk0Y2MtNjBlNi00NmRiLTk2MWYtMGMyMDlhYmI4ZDBjXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '马克·哈米尔, 哈里森·福特, 凯丽·费雪, 彼得·库欣, 亚历克·吉尼斯, 安东尼·丹尼尔斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (282, '妮尔的芳心', '剧情', 1994, '迈克尔·艾普特', '在一间偏远的森林小屋里，一个小镇医生发现了妮尔——一个拥有许多秘密的美丽年轻隐士女人。', 'https://m.media-amazon.com/images/M/MV5BNTkxY2NkMmItOTNmNy00NGU0LTlhM2UtOGQwNDhmNTBmNzQ3XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '朱迪·福斯特, 连姆·尼森, 娜塔莎·理查德森, 理查德·利伯蒂尼, 尼克·瑟西, 罗宾·马林斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (292, '恐怖地带', '动作,剧情,科幻,惊悚', 1995, '沃尔夫冈·彼德森', '一组陆军医生努力寻找一种致命莫塔巴病毒的治愈方法，这种病毒被一只白头卷尾猴从非洲带到北美，目前正在加利福尼亚一个小镇上快速传播。', 'https://m.media-amazon.com/images/M/MV5BNGYxY2Q0YzUtMmE3OS00ZmQ5LWFiOGUtZDZmNTJlM2YyZjJmXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '达斯汀·霍夫曼, 蕾妮·罗素, 摩根·弗里曼, 凯文·史派西, 小库珀·古丁, 唐纳德·萨瑟兰', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (293, '这个杀手不太冷', '动作,犯罪,剧情,惊悚', 1994, '吕克·贝松', '当她的家人被一群由专横的诺曼·斯坦斯菲尔德领导的腐败警察谋杀时，一名12岁的女孩请求一名意大利裔美国杀手的帮助来报仇。', 'https://m.media-amazon.com/images/M/MV5BNGRkYTNhOWQtYmI0Ni00MjZhLWJmMzAtMTA2Mjg4NGNiNDU0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '让·雷诺, 加里·奥德曼, 娜塔莉·波特曼, 丹尼·爱罗, 彼得·阿佩尔, 威利·万·布拉德', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (296, '低俗小说', '喜剧,犯罪,剧情,惊悚', 1994, '昆汀·塔伦蒂诺', '两名黑帮杀手、一名拳击手、一名黑帮老大及其妻子，以及一对餐厅劫匪的生活，在四个关于暴力和救赎的故事中交织在一起。', 'https://m.media-amazon.com/images/M/MV5BYTViYTE3ZGQtNDBlMC00ZTAyLTkyODMtZGRiZDg0MjA2YThkXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '蒂姆·罗斯, 阿曼达·普拉莫, 劳拉·拉芙蕾丝, 约翰·特拉沃尔塔, 塞缪尔·杰克逊, 菲尔·拉马尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (316, '星际之门', '动作,冒险,科幻', 1994, '罗兰·艾默里奇', '在埃及发现的一个星际传送装置通向了一个星球，那里的居民类似古埃及人，崇拜太阳神拉。', 'https://m.media-amazon.com/images/M/MV5BNGRmZmNhMTctZTBiMy00ZmJhLWE3MmMtMDNmZWRkZjczMGVkXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '库尔特·拉塞尔, 詹姆斯·斯派德, 杰伊·戴维森, 维韦卡·林德福斯, 亚历克西斯·克鲁兹, 米利·阿维塔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (317, '圣诞老人', '喜剧,剧情,奇幻', 1994, '约翰·帕斯奎因', '当一个男人无意中让圣诞老人从屋顶上摔下来时，他发现自己被魔法招募来接替他的位置。', 'https://m.media-amazon.com/images/M/MV5BNTYwZWUxNmUtNzdmMS00MDBiLWFhN2EtNjBmYjM1ZWFiNDUzXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '蒂姆·艾伦, 贾奇·莱茵霍尔德, 温迪·克鲁森, 埃里克·洛伊德, 大卫·克鲁霍尔特兹, 拉里·勃兰登堡', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (318, '肖申克的救赎', '犯罪,剧情', 1994, '弗兰克·德拉邦特', '一名因杀妻罪被判入狱的银行家，在坚持自己无罪并试图通过简单的同情保持希望的同时，与一名冷酷的罪犯建立了长达25年的友谊。', 'https://m.media-amazon.com/images/M/MV5BMDAyY2FhYjctNDc5OS00MDNlLThiMGUtY2UxYWVkNGY2ZjljXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '蒂姆·罗宾斯, 摩根·弗里曼, 鲍勃·冈顿, 威廉·赛德勒, 克兰西·布朗, 吉尔·贝罗斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (329, '星际旅行7：星空奇兵', '冒险,剧情,科幻', 1994, '大卫·卡森', '在被认为早已去世的柯克船长的帮助下，皮卡德船长必须阻止一名疯狂的科学家进入空间矩阵的行星级谋杀阴谋。', 'https://m.media-amazon.com/images/M/MV5BNDFjYmFmNmItODM5Ny00YzhlLWEzNjEtNTBlNjRiN2RlYTRhXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '帕特里克·斯图尔特, 乔纳森·弗雷克斯, 布伦特·斯派尔, 勒瓦尔·布尔顿, 迈克尔·多恩, 盖茨·麦克法登', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (339, '二见钟情', '喜剧,爱情', 1995, '乔·德特杜巴', '一名地铁售票员爱上了一位昏迷男子的兄弟。', 'https://m.media-amazon.com/images/M/MV5BZTJmOWIzY2YtYmE2ZC00NDRiLWIzYmMtNTkyNmNlMTA0N2NkXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '桑德拉·布洛克, 比尔·普尔曼, 彼得·盖勒, 彼得·博伊尔, 杰克·瓦尔登, 格莱妮丝·约翰斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (344, '神探飞机头', '喜剧', 1994, '汤姆·沙迪亚克', '一位专门与动物打交道的古怪侦探去寻找迈阿密海豚队失踪的吉祥物。', 'https://m.media-amazon.com/images/M/MV5BOWU1M2Q5MDgtOTkxZS00NjdmLWFlNWEtOGEyOTNlNGYyYTZlXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '金·凯瑞, 柯特妮·考克斯, 西恩·杨, 托尼·洛可, 丹·马里诺, 诺布尔·威林厄姆', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (349, '燃眉追击', '动作,犯罪,剧情,惊悚', 1994, '菲利普·诺伊斯', '中情局分析师杰克·瑞恩被卷入美国政府与哥伦比亚贩毒集团进行的一场非法战争。', 'https://m.media-amazon.com/images/M/MV5BZmRhZWJhZTctZjE4OS00NzM0LWIyYzEtNTM2MDgyY2MwNTQzXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '哈里森·福特, 威廉·达福, 安妮·阿彻, 华金·德·阿尔梅达, 亨利·科泽尼, 哈里斯·尤林', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (353, '乌鸦', '动作,犯罪,奇幻,惊悚', 1994, '亚历克斯·普罗亚斯', '就在婚礼的前一天晚上，音乐家埃里克·德雷文和他的未婚妻被一群暴力黑帮成员残忍杀害。在他们逝世一周年之际，埃里克从坟墓中复活，承担起乌鸦的衣钵，成为一名超自然的复仇者。', 'https://m.media-amazon.com/images/M/MV5BOTBiNzhkZTItZWUwZS00YTJkLTg0YTEtN2I0ZDI5ODI2MWFjXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '李国豪, 罗谢尔·戴维斯, 厄尼·哈德森, 迈克尔·温柯特, 白灵, 索菲亚·希纳斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (355, '石头族乐园', '儿童,喜剧,奇幻', 1994, '布莱恩·莱温特', '在一个平行的现代石器时代世界里，一个工人阶级家庭——弗林特斯一家——被安排担任高管职位。但他们明白了金钱买不到幸福。', 'https://m.media-amazon.com/images/M/MV5BZmQwYjljNjUtYjA0NC00MTEyLWE0YmItNGViNGU5ZDEzMWRiXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '约翰·古德曼, 伊丽莎白·帕金斯, 里克·莫拉尼斯, 罗西·奥唐纳, 凯尔·麦克拉克伦, 哈莉·贝瑞', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (356, '阿甘正传', '喜剧,剧情,爱情,战争', 1994, '罗伯特·泽米吉斯', '从20世纪50年代到70年代的美国历史，从一位智商为75的阿拉巴马州男子的视角展开，他渴望与童年时的甜心重聚。', 'https://m.media-amazon.com/images/M/MV5BNDYwNzVjMTItZmU5YS00YjQ5LTljYjgtMjY2NDVmYWMyNWFmXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '汤姆·汉克斯, 丽贝卡·威廉姆斯, 莎莉·菲尔德, 迈克尔·康纳·汉弗莱斯, 哈罗德·G·赫瑟姆, 乔治·凯利', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (357, '四个婚礼和一个葬礼', '喜剧,爱情', 1994, '迈克·内威尔', '在五个社交场合的过程中，一位坚定的单身汉必须考虑他可能已经发现爱情的可能性。', 'https://m.media-amazon.com/images/M/MV5BMTMyNzg2NzgxNV5BMl5BanBnXkFtZTcwMTcxNzczNA@@._V1_FMjpg_UX1000_.jpg', '休·格兰特, 詹姆斯·弗利特, 西蒙·卡洛, 约翰·汉纳, 克里斯汀·斯科特·托马斯, 大卫·鲍尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (364, '狮子王', '冒险,动画,儿童,剧情,音乐,IMAX', 1994, '罗杰·阿勒斯', '狮子王子辛巴和他的父亲成为他怀恨在心的叔叔的目标，后者想自己登上王位。', 'https://m.media-amazon.com/images/M/MV5BZGRiZDZhZjItM2M3ZC00Y2IyLTk3Y2MtMWY5YjliNDFkZTJlXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '罗温·阿特金森, 马修·布罗德里克, 妮基塔·卡拉姆-哈里斯, 吉姆·卡明斯, 乌比·戈德堡, 罗伯特·纪尧姆', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (367, '变相怪杰', '动作,喜剧,犯罪,奇幻', 1994, '查克·拉塞尔', '银行职员斯坦利·伊普基斯戴上一个神秘面具后变成了一个疯狂的超级英雄。', 'https://m.media-amazon.com/images/M/MV5BNGNmNjI0ZmMtMzI5MC00ZjUyLWFlZDEtYjUyMGZlN2E3N2E2XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '金·凯瑞, 彼得·里格特, 彼得·格林, 艾米·雅丝贝克, 理查德·杰尼, 奥雷斯特斯·马塔塞纳', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (370, '白头神探3：最后的耻辱', '动作,喜剧', 1994, '彼得·西格尔', '弗兰克·德宾从退休中复出，帮助警察小队渗透一个计划在奥斯卡颁奖典礼上引爆炸弹的恐怖分子团伙。', 'https://m.media-amazon.com/images/M/MV5BM2ViYTFhMTktMjU0OC00ZWY3LWEzZDItMTExNDc2NDNjN2I3XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '莱斯利·尼尔森, 普里西拉·普雷斯利, 乔治·肯尼迪, O·J·辛普森, 弗雷德·沃德, 凯瑟琳·弗里曼', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (377, '生死时速', '动作,爱情,惊悚', 1994, '扬·德·邦特', '一名敲诈勒索的炸弹袭击者将洛杉矶的一辆城市公共汽车做了手脚，如果车速低于50英里/小时就会爆炸，迫使一名年轻警察和一名女乘客保持其行驶并拯救车上的所有人。', 'https://m.media-amazon.com/images/M/MV5BMDc2ODI5YWQtMmM2ZS00MTdmLWEyNWEtNmRmOGE5NGZlYWMzXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '基努·里维斯, 丹尼斯·霍珀, 桑德拉·布洛克, 乔·莫顿, 杰夫·丹尼尔斯, 艾伦·卢克', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (380, '真实的谎言', '动作,冒险,喜剧,爱情,惊悚', 1994, '詹姆斯·卡梅隆', '一位无所畏惧、周游全球、与恐怖分子作战的秘密特工发现他的妻子可能与一个二手车推销员有染，而恐怖分子正将核弹头走私到美国，这使他的生活天翻地覆。', 'https://m.media-amazon.com/images/M/MV5BYjU1ZjNhMjMtOTMxZS00MDc1LTlkNzQtZTdjNGQyYjQ4YTA4XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '阿诺德·施瓦辛格, 杰米·李·柯蒂斯, 汤姆·阿诺德, 比尔·帕克斯顿, 蒂亚·卡雷尔, 阿特·马利克', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (410, '亚当斯一家的价值观', '儿童,喜剧,奇幻', 1993, '巴里·索南菲尔德', '亚当斯一家试图从他们心爱的费斯特叔叔的新欢——一个名叫黛比的“黑寡妇”那里救出他。', 'https://m.media-amazon.com/images/M/MV5BYWY3Y2ZkYjktZWYxMC00ZmZmLTgxNjYtYmMwYmU5OWJjMThjXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '安杰丽卡·休斯顿, 劳尔·朱莉娅, 克里斯托弗·洛伊德, 琼·库萨克, 克里斯蒂娜·里奇, 卡罗尔·凯恩', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (434, '绝岭雄风', '动作,冒险,惊悚', 1993, '雷尼·哈林', '两名山地救援人员被迫为一群盗贼带路，寻找他们丢失的财物。', 'https://m.media-amazon.com/images/M/MV5BNGJkZmZlYTYtODQ1ZC00N2JiLWIxMWYtZTE4ZDMxZjQyZTAzXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '西尔维斯特·史泰龙, 约翰·利特高, 迈克尔·鲁克, 珍妮·特里普里霍恩, 雷克斯·林恩, 卡罗琳·古多尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (442, '超级战警', '动作,冒险,科幻', 1993, '马可·布拉姆贝拉', '一名警官从监狱的暂停状态中被唤醒，以追捕一个在非暴力的未来社会中逍遥法外的旧日极度暴力的死敌。', 'https://m.media-amazon.com/images/M/MV5BNWY3ZThmN2QtMzVkNS00MjczLTllNDQtOGEwN2M0ZTFkMWMzXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '西尔维斯特·史泰龙, 韦斯利·斯奈普斯, 桑德拉·布洛克, 奈杰尔·霍桑, 本杰明·布拉特, 鲍勃·冈顿', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (454, '糖衣陷阱', '剧情,惊悚', 1993, '西德尼·波拉克', '一位年轻律师加入一家著名的律师事务所，却发现它有阴险的黑暗面。', 'https://m.media-amazon.com/images/M/MV5BMjE3ZDZkMWMtY2RkMC00YzJjLWFhYTUtYmRjMzAyMzEwZDE5XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '汤姆·克鲁斯, 珍妮·特里普里霍恩, 吉恩·哈克曼, 哈尔·霍尔布鲁克, 特里·金尼, 威尔福德·布利姆雷', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (457, '亡命天涯', '惊悚', 1993, '安德鲁·戴维斯', '被冤枉谋杀妻子的理查德·金博尔博士必须在成为经验丰富的美国法警领导的全美追捕目标的同时，找到真正的凶手。', 'https://m.media-amazon.com/images/M/MV5BM2RjMjEwODUtYTE4OC00MzhkLThjMjItZjYyZjk3YzA4YWUxXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '哈里森·福特, 汤米·李·琼斯, 塞拉·沃德, 朱丽安·摩尔, 乔·潘托里亚诺, 安德烈亚斯·卡楚拉斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (466, '反斗神鹰2', '动作,喜剧,战争', 1993, '吉姆·亚伯拉罕斯', '恶搞“第一滴血”，托珀·哈利带领一支救援队进入伊拉克，营救伊拉克战俘及其之前所有的救援队。', 'https://m.media-amazon.com/images/M/MV5BNGU5ZTUzMmQtZDI3Yy00Y2ZlLTg1MmMtYWZiNDYyYmI4YmE2XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '查理·辛, 劳埃德·布里奇斯, 瓦莱里亚·戈利诺, 理查德·克里纳, 布伦达·巴可, 米盖尔·弗尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (474, '火线狙击', '动作,惊悚', 1993, '沃尔夫冈·彼德森', '特勤局特工弗兰克·霍里根没能救下肯尼迪，但他决心不让一个聪明的刺客干掉这位总统。', 'https://m.media-amazon.com/images/M/MV5BYmNiNjNjYmQtZTQzNC00M2I1LThiMDgtNWNmM2VjY2Y3NzQxXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '克林特·伊斯特伍德, 约翰·马尔科维奇, 蕾妮·罗素, 迪伦·麦克德莫特, 加里·科尔, 弗雷德·道尔顿·汤普森', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (480, '侏罗纪公园', '动作,冒险,科幻,惊悚', 1993, '史蒂文·斯皮尔伯格', '一位实业家邀请一些专家参观他的克隆恐龙主题公园。停电后，恐龙四处乱跑，危及每个人的生命，包括他孙辈的生命。', 'https://m.media-amazon.com/images/M/MV5BMjM2MDgxMDg0Nl5BMl5BanBnXkFtZTgwNTM2OTM5NDE@._V1_FMjpg_UX1000_.jpg', '山姆·尼尔, 劳拉·邓恩, 杰夫·高布伦, 理查德·阿滕伯勒, 鲍勃·佩克, 马丁·费雷罗', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (485, '幻影英雄', '动作,冒险,喜剧,奇幻', 1993, '约翰·麦克蒂尔南', '在一张神奇电影票的帮助下，一位年轻的影迷被传送进了他最喜爱的动作电影角色的虚构世界。', 'https://m.media-amazon.com/images/M/MV5BZGU2NWQyY2ItY2JiZS00ZDJhLWI0NDQtNjMyNWU3MDA1NTgzXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '阿诺德·施瓦辛格, F·默里·亚伯拉罕, 阿特·卡尼, 查尔斯·丹斯, 弗兰克·麦克雷, 汤姆·努南', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (494, '最高危机', '动作,冒险,惊悚', 1996, '斯图尔特·贝尔德', '当恐怖分子劫持一架客机时，一名情报分析员随同一支突击队进行了一次空中登机行动。', 'https://m.media-amazon.com/images/M/MV5BYTExYWQzMWMtZjdjYy00OWQ3LWJjY2ItYjU4YWQ4M2NmMTJlXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '库尔特·拉塞尔, 史蒂文·西格尔, 哈莉·贝瑞, 约翰·雷吉扎莫, 奥利弗·普莱特, 乔·莫顿', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (500, '窈窕奶爸', '喜剧,剧情', 1993, '克里斯·哥伦布', '在痛苦的离婚后，一位演员伪装成一名女管家，以便与由前妻监护的孩子们共度时光。', 'https://m.media-amazon.com/images/M/MV5BY2E2MDc5ZGEtOTNlZS00Mjg4LThlNzUtMDY2Zjc4ZTViNWY0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '罗宾·威廉姆斯, 莎莉·菲尔德, 皮尔斯·布鲁斯南, 哈维·费斯特恩, 波利·霍利迪, 丽莎·雅各布', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (508, '费城故事', '剧情', 1993, '乔纳森·戴米', '当一名感染HIV的男子因其病情被他的律师事务所解雇时，他聘请了一名恐同的小律师作为唯一愿意代理其不当解雇诉讼的辩护人。', 'https://m.media-amazon.com/images/M/MV5BYzEzZmMwMmMtNDgxYi00YTAwLWFkMjQtOGQzNmUxMGU1YWYwXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '汤姆·汉克斯, 丹泽尔·华盛顿, 罗伯塔·马克斯韦尔, 巴兹·基尔曼, 凯伦·芬利, 丹尼尔·查普曼', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (509, '钢琴课', '剧情,爱情', 1993, '简·坎皮恩', '在19世纪中期，一位哑女和她年幼的女儿以及她珍视的钢琴被送到新西兰，与一位农民进行包办婚姻，但她很快就被一名农场工人垂涎。', 'https://m.media-amazon.com/images/M/MV5BZGZiYTQ0MmEtY2RmYy00ZjRkLWI3NTctYTRhMGJlMzA4ZDg0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '霍利·亨特, 哈威·凯特尔, 山姆·尼尔, 安娜·帕奎因, 克里·沃克, 热纳维耶芙·莱蒙', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (520, '罗宾汉也疯狂', '喜剧', 1993, '梅尔·布鲁克斯', '恶搞罗宾汉，特别是对1991年侠盗王子罗宾汉的恶搞。', 'https://m.media-amazon.com/images/M/MV5BY2ZkMGU1OGUtZTJlOS00MmE5LWIxZjQtYWRlZDljMGJkMTZmXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '加利·艾尔维斯, 理查德·刘易斯, 罗杰·里斯, 艾米·雅丝贝克, 马克·布兰克菲尔德, 戴夫·查普尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (524, '追梦赤子心', '剧情', 1993, '大卫·安斯帕夫', '鲁迪总是被告知他太小了，打不了大学橄榄球。但他决心克服困难，实现为圣母大学打球的梦想。', 'https://m.media-amazon.com/images/M/MV5BNjQ1MWQ4MWQtZWQzMy00NmU1LThmYzItNGU1OTc5MWJjNzQ1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '西恩·奥斯汀, 乔恩·费儒, 尼德·巴蒂, 格蕾塔·林德, 斯科特·本杰明森, 玛丽·安·塞布斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (527, '辛德勒的名单', '剧情,战争', 1993, '史蒂文·斯皮尔伯格', '在二战期间德国占领的波兰，实业家奥斯卡·辛德勒在目睹他的犹太员工遭受纳粹迫害后，逐渐开始关心他们。', 'https://m.media-amazon.com/images/M/MV5BNjM1ZDQxYWUtMzQyZS00MTE1LWJmZGYtNGUyNTdlYjM3ZmVmXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '连姆·尼森, 本·金斯利, 拉尔夫·费因斯, 卡罗琳·古多尔, 乔纳森·萨加尔, 艾姆博特·大卫兹', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (539, '西雅图夜未眠', '喜剧,剧情,爱情', 1993, '诺拉·艾芙隆', '一位最近丧偶的男子的儿子打电话给电台谈话节目，试图为父亲寻找伴侣。', 'https://m.media-amazon.com/images/M/MV5BZmU1MzlmOTMtZTNmMC00ZTA3LTkzMWMtOTc1MWNlMjFiYjFlXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '汤姆·汉克斯, 罗斯·马林格, 丽塔·威尔逊, 维克多·加伯, 汤姆·里斯·法雷尔, 凯瑞·洛厄尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (541, '银翼杀手', '动作,科幻,惊悚', 1982, '雷德利·斯科特', '一名银翼杀手必须追捕并消灭四个偷窃太空船并返回地球寻找创造者的复制人。', 'https://m.media-amazon.com/images/M/MV5BOWQ4YTBmNTQtMDYxMC00NGFjLTkwOGQtNzdhNmY1Nzc1MzUxXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '哈里森·福特, 鲁特格尔·哈尔, 肖恩·杨, 爱德华·詹姆斯·奥莫斯, M·埃米特·沃尔什, 达丽尔·汉纳', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (551, '圣诞夜惊魂', '动画,儿童,奇幻,音乐', 1993, '亨利·塞利克', '万圣节镇的国王杰克·斯凯灵顿发现了圣诞节镇，但他试图将圣诞节带到家乡却引发了混乱。', 'https://m.media-amazon.com/images/M/MV5BNmYxOTAzZWYtOGI3Yi00ODc3LTk5ZjYtZTY0MzVkZTg3YmRiXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '丹尼·艾夫曼, 克里斯·萨兰登, 凯瑟琳·欧哈拉, 威廉·赫基, 格伦·沙迪克斯, 保罗·雷宾斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (555, '真实浪漫', '犯罪,惊悚', 1993, '托尼·斯科特', '在底特律，一位流行文化爱好者从新婚妻子的皮条客那里偷了可卡因，并试图在好莱坞出售，导致拥有毒品的黑帮分子追捕这对夫妇。', 'https://m.media-amazon.com/images/M/MV5BYzQ5OGMwMDAtMzcyOS00YTA4LWEwM2MtOTA1MDZjZGEyYmI1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '克里斯蒂安·斯莱特, 帕特丽夏·阿奎特, 丹尼斯·霍珀, 瓦尔·基尔默, 加里·奥德曼, 布拉德·皮特', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (588, '阿拉丁', '冒险,动画,儿童,喜剧,音乐', 1992, '罗恩·克莱蒙兹', '一位好心的街头流浪儿和一个权力欲强的宰相争夺一盏能实现他们最深愿望的神灯。', 'https://m.media-amazon.com/images/M/MV5BMmQwYWZjZGItYzc0OC00ZDllLTg3NjItOWIyOWYwMDljMjAyXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '斯科特·维格, 罗宾·威廉姆斯, 琳达·拉金, 乔纳森·弗里曼, 弗兰克·维尔克, 吉尔伯特·戈特弗里德', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (589, '终结者2：审判日', '动作,科幻', 1991, '詹姆斯·卡梅隆', '一个与未能杀死莎拉·康纳的终结者相同的机器人，现在必须保护她十岁的儿子约翰免受一个更先进、更强大的终结者的伤害。', 'https://m.media-amazon.com/images/M/MV5BNGMyMGNkMDUtMjc2Ni00NWFlLTgyODEtZTY2MzBiZTg0OWZiXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '阿诺德·施瓦辛格, 琳达·汉密尔顿, 爱德华·福隆, 罗伯特·帕特里克, 厄尔·波恩, 乔·莫顿', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (590, '与狼共舞', '冒险,剧情,西部', 1990, '凯文·科斯特纳', '一名被指派到偏远内战前哨站的中尉在与邻近的苏族定居点接触后，开始质疑自己的目的。', 'https://m.media-amazon.com/images/M/MV5BMTY3OTI5NDczN15BMl5BanBnXkFtZTcwNDA0NDY3Mw@@._V1_FMjpg_UX1000_.jpg', '凯文·科斯特纳, 玛丽·麦克唐纳, 格雷厄姆·格林, 罗德尼·A·格兰特, 弗洛伊德·雷德克劳·韦斯特曼, 坦图·卡迪纳尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (592, '蝙蝠侠', '动作,犯罪,惊悚', 1989, '蒂姆·伯顿', '哥谭市的黑暗骑士开始了他对犯罪的战争，他的第一个主要敌人是杰克·纳皮尔，一个变成小丑般杀人狂的罪犯。', 'https://m.media-amazon.com/images/M/MV5BYzZmZWViM2EtNzhlMi00NzBlLWE0MWEtZDFjMjk3YjIyNTBhXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '迈克尔·基顿, 杰克·尼科尔森, 金·贝辛格, 罗伯特·沃uhl, 帕特·亨格尔, 比利·迪·威廉姆斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (593, '沉默的羔羊', '犯罪,恐怖,惊悚', 1991, '乔纳森·戴米', '一名年轻的FBI学员必须接受一名被监禁且操纵性的食人杀手的帮助，以抓捕另一个剥皮受害者的连环杀手。', 'https://m.media-amazon.com/images/M/MV5BNDdhOGJhYzctYzYwZC00YmI2LWI0MjctYjg4ODdlMDExYjBlXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '朱迪·福斯特, 安东尼·霍普金斯, 斯科特·格伦, 泰德·莱文, 安东尼·希尔德, 布鲁克·史密斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (594, '白雪公主和七个小矮人', '动画,儿童,剧情,奇幻,音乐', 1937, '威廉·科特雷尔', '被邪恶的继母放逐到危险的森林中，一位公主被七个小矮人矿工救起，他们让她成为家庭的一部分。', 'https://m.media-amazon.com/images/M/MV5BMTQwMzE2Mzc4M15BMl5BanBnXkFtZTcwMTE4NTc1Nw@@._V1_FMjpg_UX1000_.jpg', '罗伊·阿特威尔, 斯图尔特·布坎南, 阿德里亚娜·卡塞洛蒂, 埃迪·柯林斯, 平托·科尔维格, 玛丽昂·达林顿', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (595, '美女与野兽', '动画,儿童,奇幻,音乐,爱情,IMAX', 1991, '加里·特鲁茨代尔', '一位被诅咒白天变成丑陋野兽的王子，通过赢得一位年轻女子的爱来重获人性。', 'https://m.media-amazon.com/images/M/MV5BYTY3NDg2YzktYWFjZC00MTExLTlmZDctMGY3MWYzZTlkYTNiXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '罗比·本森, 杰西·科蒂, 雷克斯·埃弗哈特, 安吉拉·兰斯伯里, 佩吉·奥哈拉, 杰里·奥巴赫', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (597, '风月俏佳人', '喜剧,爱情', 1990, '加里·马歇尔', '一位企业掠夺者雇佣一名妓女在加利福尼亚比佛利山庄充当商业陪衬。', 'https://m.media-amazon.com/images/M/MV5BNjk2ODQzNDYxNV5BMl5BanBnXkFtZTgwMTcyNDg4NjE@._V1_FMjpg_UX1000_.jpg', '理查·基尔, 朱莉娅·罗伯茨, 拉尔夫·贝拉米, 杰森·亚历山大, 劳拉·桑·吉亚科莫, 亚历克斯·海德-怀特', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (608, '冰血暴', '喜剧,犯罪,剧情,惊悚', 1996, '乔尔·科恩', '明尼苏达州汽车销售员杰瑞·伦德加德的拙劣犯罪由于他和他的手下的笨拙以及相当怀孕的玛吉·冈德森坚持不懈的警务工作而瓦解。', 'https://m.media-amazon.com/images/M/MV5BNjg4MWE0MjEtODFhNy00MjA5LTg5ODktMzgwNWFmZTAwNjBlXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '威廉·H·梅西, 史蒂夫·布西密, 彼得·斯特曼, 克里斯汀·鲁德鲁德, 哈维·普雷斯内尔, 托尼·丹曼', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (616, '贵族猫', '动画,儿童', 1970, '沃尔夫冈·雷瑟曼', '在一只能言善道的公猫的帮助下，一窝巴黎猫在从主人那里继承财富后，被嫉妒的管家绑架并遗弃在乡下，试图返回家园。', 'https://m.media-amazon.com/images/M/MV5BMTU1MzM0MjcxMF5BMl5BanBnXkFtZTgwODQ0MzcxMTE@._V1_FMjpg_UX1000_.jpg', '菲尔·哈里斯, 伊娃·伽伯, 斯特林·霍洛韦, 斯卡特曼·克罗瑟斯, 保罗·温切尔, 洛德·蒂姆·哈德森', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (648, '碟中谍', '动作,冒险,神秘,惊悚', 1996, '布莱恩·德·帕尔玛', '一名被错误怀疑不忠的美国特工，必须在没有组织帮助的情况下发现并揭露真正的间谍。', 'https://m.media-amazon.com/images/M/MV5BOGZjNDlkMTYtMTJkZi00OTkzLWI4NDEtYTA2ODQyMjcwYTdlXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '汤姆·克鲁斯, 乔恩·沃伊特, 艾曼纽·贝阿, 亨利·科泽尼, 让·雷诺, 文·瑞姆斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (653, '龙之心', '动作,冒险,奇幻', 1996, '罗伯·科恩', '最后一条龙和一位幻想破灭的屠龙骑士必须联合起来，阻止一位被授予部分永生的邪恶国王。', 'https://m.media-amazon.com/images/M/MV5BZDViYjIxNjgtMmEyNS00MmVlLTllOWMtMGU0NzEwZjU2ZTYzXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '丹尼斯·奎德, 大卫·休里斯, 皮特·波斯尔思韦特, 迪娜·迈耶, 杰森·艾萨克斯, 布莱恩·汤普森', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (673, '太空大灌篮', '冒险,动画,儿童,喜剧,奇幻,科幻', 1996, '乔·皮特卡', '为了赢得篮球比赛并获得自由，乐一通卡通角色寻求退役篮球冠军迈克尔·乔丹的帮助。', 'https://m.media-amazon.com/images/M/MV5BZGQ3ZDk0M2MtZDNmNi00OWE3LThiODUtMTU3NmVjMTA0ZGQyXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '迈克尔·乔丹, 韦恩·奈特, 特蕾莎·兰德尔, 曼纳·华盛顿三世, 埃里克·戈登, 彭尼·贝·布里奇斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (733, '勇闯夺命岛', '动作,冒险,惊悚', 1996, '迈克尔·贝', '一名FBI化学武器专家和一名前SAS士兵转政治犯，必须闯入阿尔卡特拉斯监狱，因为一个由叛变将军领导的流氓军事团体接管了它，并威胁对旧金山发动神经毒气攻击。', 'https://m.media-amazon.com/images/M/MV5BMDhkYjRiZWEtZTE0Ny00ZjA1LThmNjgtM2UyYTQzODA4MjdhXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '肖恩·康纳利, 尼古拉斯·凯奇, 艾德·哈里斯, 约翰·斯宾塞, 大卫·莫尔斯, 威廉·弗西斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (736, '龙卷风', '动作,冒险,爱情,惊悚', 1996, '扬·德·邦特', '一对濒临离婚的暴风追逐者必须合作，通过将自己置于极端暴力龙卷风的瞄准线中，创建一个先进的天气警报系统。', 'https://m.media-amazon.com/images/M/MV5BNGVhY2JjYzgtYjAyOC00ODg0LTliYWEtMzliZWYzMjA2NjYyXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '海伦·亨特, 比尔·帕克斯顿, 贾米·格尔茨, 卡里·埃尔维斯, 洛伊丝·史密斯, 菲利普·塞默·霍夫曼', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (741, '攻壳机动队', '动画,科幻', 1995, '押井守', '一名生化人女警和她的搭档追捕一个名为傀儡师的神秘而强大的黑客。', 'https://m.media-amazon.com/images/M/MV5BNzljMjA3MTQtMjM1OS00OGJjLWJiYzctZDRiMTk1NWI5YzQ5XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '田中敦子, 大冢明夫, 山寺宏一, 中谷由美, 大木民夫, 玄田哲章', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (745, '超级无敌掌门狗：剃刀边缘', '动画,儿童,喜剧', 1995, '尼克·帕克', '华莱士与当地羊毛店老板的旋风恋情让他头晕目眩；格罗米被卷入一个邪恶的犯罪阴谋中，被诬陷偷羊。', 'https://m.media-amazon.com/images/M/MV5BM2M4ZmEzYzEtNjk0ZS00ODZkLTkxZjYtNTY4Njg2YjhhMWNkXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '彼得·萨利斯, 安妮·雷德, 贾斯汀·弗莱彻', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (750, '奇爱博士', '喜剧,战争', 1964, '斯坦利·库布里克', '一位精神不稳定的美国将军命令对苏联发动氢弹攻击，引发了一场全球核毁灭之路，满屋的政治家和将军们疯狂地试图阻止。', 'https://m.media-amazon.com/images/M/MV5BMTkxNGFlNDktZmJkNC00MDdhLTg0MTEtZjZiYWI3MGE5NWIwXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '彼得·塞勒斯, 乔治·C·斯科特, 斯特林·海登, 基南·怀恩, 斯利姆·皮肯斯, 彼得·布尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (778, '猜火车', '喜剧,犯罪,剧情', 1996, '丹尼·博伊尔', '深陷爱丁堡毒品场景的雷顿试图清理自己并脱身，尽管毒品和朋友的影响充满诱惑。', 'https://m.media-amazon.com/images/M/MV5BZmVjNzQ3MjYtYTZiNC00Y2YzLWExZTEtMTM2ZDllNDI0MzgyXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '伊万·麦克格雷格, 艾文·布莱纳, 乔尼·李·米勒, 凯文·麦基德, 罗伯特·卡莱尔, 凯莉·麦克唐纳', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (780, '独立日', '动作,冒险,科幻,惊悚', 1996, '罗兰·艾默里奇', '外星人来了，他们的目标是入侵并摧毁地球。面对先进的技术，人类最好的武器是生存的意志。', 'https://m.media-amazon.com/images/M/MV5BOGMwN2UwZjEtYjFjMi00ZDA1LWJlYTQtMjA1MTYxMzIyNTdiXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '威尔·史密斯, 比尔·普尔曼, 杰夫·高布伦, 玛丽·麦克唐纳, 贾德·赫希, 罗伯特·洛吉亚', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (783, '钟楼怪人', '动画,儿童,剧情,音乐,爱情', 1996, '加里·特鲁茨代尔', '一位畸形的敲钟人必须断言自己独立于恶毒的政府部长，以帮助他的朋友，一位吉普赛舞者。', 'https://m.media-amazon.com/images/M/MV5BY2QzMGEzNGMtMDQyNC00YTlmLWEwYjMtOGI1NWYxMTM4NjA2XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '杰森·亚历山大, 玛丽·凯·伯格曼, 科里·伯顿, 吉姆·卡明斯, 比尔·法格巴克, 汤姆·休斯克', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (802, '不一样的本能', '剧情,爱情', 1996, '乔·特特拉布', '一个小镇的普通人变成了一个拥有心灵感应能力的天才。', 'https://m.media-amazon.com/images/M/MV5BMjAwMDA2NzEyMl5BMl5BanBnXkFtZTgwNTA2MjgxMTE@._V1_FMjpg_UX1000_.jpg', '约翰·特拉沃尔塔, 凯拉·塞吉维克, 福里斯特·惠特克, 罗伯特·杜瓦尔, 杰弗里·德曼, 理查德·基利', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (805, '杀戮时刻', '剧情,惊悚', 1996, '乔尔·舒马赫', '一位年轻的密西西比律师为一名杀死强奸他未成年女儿的两名白人男子的黑人辩护。', 'https://m.media-amazon.com/images/M/MV5BYmNiYzY1N2ItZDZiNC00ZGMyLWJlZjktZDE1MDI3NDBlYjE5XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '马修·麦康纳, 桑德拉·布洛克, 塞缪尔·杰克逊, 凯文·史派西, 奥利弗·普莱特, 查尔斯·S·达顿', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (858, '教父', '犯罪,剧情', 1972, '弗朗西斯·福特·科波拉', '一个有组织犯罪王朝的年迈族长将他的秘密帝国控制权转移给他不情愿的儿子。', 'https://m.media-amazon.com/images/M/MV5BNGEwYjgwOGQtYjg5ZS00Njc1LTk2ZGEtM2QwZWQ2NjdhZTE5XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '马龙·白兰度, 阿尔·帕西诺, 詹姆斯·肯恩, 理查德·S·卡斯特拉诺, 罗伯特·杜瓦尔, 斯特林·海登', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (898, '费城故事', '喜剧,剧情,爱情', 1940, '乔治·库克', '一位富有的女人的前夫和一名小报记者在她计划再婚前出现，她开始了解自己的真相。', 'https://m.media-amazon.com/images/M/MV5BYmMwZTQ5OGUtMjQ4Ni00ZTIwLTk1ZWMtNzhlMGQxYjIxMTU1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '加里·格兰特, 凯瑟琳·赫本, 詹姆斯·斯图尔特, 露丝·赫西, 约翰·霍华德, 罗兰·杨', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (902, '蒂凡尼的早餐', '剧情,爱情', 1961, '布莱克·爱德华兹', '一位年轻的纽约社交名媛对搬进她公寓楼的年轻男子产生兴趣，但她的过去威胁要阻碍她。', 'https://m.media-amazon.com/images/M/MV5BYmYxZTE3YzMtYmE2Yy00NmFlLTkzYTAtYTAzN2IzNDFkN2E0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '奥黛丽·赫本, 乔治·佩帕德, 帕特里夏·尼尔, 巴迪·埃布森, 马丁·鲍尔萨姆, 何塞·路易斯·德维拉隆加', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (904, '后窗', '神秘,惊悚', 1954, '阿尔弗雷德·希区柯克', '一名因腿骨折无聊的摄影师通过观察邻居来打发时间，并开始怀疑其中一人谋杀。', 'https://m.media-amazon.com/images/M/MV5BODZhOWI1ODgtMzdiOS00YjNkLTgwOGUtYmIyZDg5ZmQwMzQ1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '詹姆斯·斯图尔特, 格蕾丝·凯利, 温德尔·科里, 塞尔玛·里特, 雷蒙德·布尔, 朱迪思·伊夫林', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (908, '西北偏北', '动作,冒险,悬疑,爱情,惊悚', 1959, '阿尔弗雷德·希区柯克', '一名纽约广告主管被外国间谍误认为是政府特工而被迫逃亡，并爱上了一名他开始怀疑其忠诚度的女人。', 'https://m.media-amazon.com/images/M/MV5BZWIzODI2OGItMzM0Ny00OGRmLTlkNmItMDQxMTFmMTk3YmQwXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '加里·格兰特, 伊娃·玛丽·圣, 詹姆斯·梅森, 杰西·罗伊斯·兰迪斯, 利奥·G·卡罗尔, 约瑟芬·哈钦森', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (909, '公寓', '喜剧,剧情,爱情', 1960, '比利·怀尔德', '一名曼哈顿保险职员通过让公司高管使用他的公寓进行幽会来试图晋升，但办公室政治和他自己的浪漫希望使事情复杂化。', 'https://m.media-amazon.com/images/M/MV5BNDdhMzVhOWQtNDU2Mi00ZmZmLWJiZDMtY2QxMjhjY2Y1ZTI5XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '杰克·莱蒙, 雪莉·麦克雷恩, 弗雷德·麦克默里, 雷·沃尔斯顿, 杰克·克鲁申, 大卫·刘易斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (912, '卡萨布兰卡', '剧情,爱情', 1942, '迈克尔·柯蒂兹', '一位愤世嫉俗的美国侨民咖啡馆老板在法属摩洛哥挣扎着决定是否帮助他的前情人和她的逃亡丈夫逃离纳粹。', 'https://m.media-amazon.com/images/M/MV5BNWEzN2U1YTYtYTQyMS00NTVkLWE2NGQtZWFlMmM0MDNjMmRiXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '亨弗莱·鲍嘉, 英格丽·褒曼, 保罗·亨雷德, 克劳德·雷恩斯, 康拉德·韦特, 悉尼·格林斯特里特', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (919, '绿野仙踪', '冒险,儿童,奇幻,歌舞', 1939, '维克多·弗莱明', '年轻的多萝西·盖尔和她的狗托托被龙卷风从堪萨斯农场卷到神奇的奥兹国，并与三个新朋友一起踏上旅程去见巫师。', 'https://m.media-amazon.com/images/M/MV5BYWRmY2I0MGItYTQ0OC00NWZmLWIwMDktYjJlNDc0MzVhMmViXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '朱迪·加兰, 弗兰克·摩根, 雷·博尔格, 伯特·拉尔, 杰克·哈利, 比莉·伯克', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (920, '乱世佳人', '剧情,爱情,战争', 1939, '维克多·弗莱明', '一个受庇护且善于操纵的南方美女和一个流氓投机者在动荡的浪漫中对抗，围绕他们的社会随着奴隶制的终结而崩溃。', 'https://m.media-amazon.com/images/M/MV5BYmYxZTE3YzMtYmE2Yy00NmFlLTkzYTAtYTAzN2IzNDFkN2E0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '托马斯·米切尔, 芭芭拉·奥尼尔, 费雯·丽, 伊芙琳·凯斯, 安·卢瑟福德, 乔治·里维斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (923, '公民凯恩', '剧情,悬疑', 1941, '奥逊·威尔斯', '出版业大亨查尔斯·福斯特·凯恩去世后，记者们争先恐后地揭开他最后遗言\"玫瑰花蕾\"的含义。', 'https://m.media-amazon.com/images/M/MV5BYjk1ZDJlMmUtOWQ0Zi00MDM5LTk1OGYtODczNjFmMGYwZGVkXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '约瑟夫·科顿, 多萝西·康明戈尔, 阿格妮丝·摩尔海德, 露丝·沃里克, 雷·柯林斯, 厄斯金·桑福德', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (924, '2001太空漫游', '冒险,剧情,科幻', 1968, '斯坦利·库布里克', '当月球上发现一个神秘文物时，一艘由两名人类和一台超级计算机驾驶的宇宙飞船被派往木星寻找其起源。', 'https://m.media-amazon.com/images/M/MV5BNjU0NDFkMTQtZWY5OS00MmZhLTg3Y2QtZmJhMzMzMWYyYjc2XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '凯尔·杜拉, 加里·洛克伍德, 威廉·西尔维斯特, 丹尼尔·里希特, 伦纳德·罗西特, 玛格丽特·泰扎克', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (928, '蝴蝶梦', '剧情,悬疑,爱情,惊悚', 1940, '阿尔弗雷德·希区柯克', '一个自我意识强烈的女人在适应她作为贵族妻子的新角色和避免被他的第一任妻子的幽灵般的存在所吓倒之间挣扎。', 'https://m.media-amazon.com/images/M/MV5BYTI0MjUyODAtZTBkNC00MmIwLWFlNmYtMWE3ZmJlOWJjM2QyXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '劳伦斯·奥利弗, 琼·芳登, 乔治·桑德斯, 朱迪思·安德森, 奈杰尔·布鲁斯, 雷金纳德·丹尼', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (953, '生活多美好', '儿童,剧情,奇幻,爱情', 1946, '弗兰克·卡普拉', '一位天使从天堂被派来帮助一个极度沮丧的商人看到他生命的价值。', 'https://m.media-amazon.com/images/M/MV5BMDM4OWFhYjEtNTE5Yy00NjcyLTg5N2UtZDQwNDZlYjlmNDU5XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '詹姆斯·斯图尔特, 唐娜·里德, 莱昂纳尔·巴里摩尔, 托马斯·米切尔, 亨利·特拉弗斯, 比拉·邦迪', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (969, '非洲女王号', '冒险,喜剧,爱情,战争', 1951, '约翰·休斯顿', '在第一次世界大战的东非，一个酗酒的加拿大河船船长被一个严谨的英国传教士说服，沿着一条危险的河流航行。', 'https://m.media-amazon.com/images/M/MV5BY2Y0OWQ4Y2QtNGE5NC00MDk4LWFlYmQtYWVmNzZlZWVhMTg4XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '亨弗莱·鲍嘉, 凯瑟琳·赫本, 罗伯特·莫利, 彼得·布尔, 西奥多·比克尔, 沃尔特·高特尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1022, '灰姑娘', '动画,儿童,奇幻,歌舞,爱情', 1950, '克莱德·杰洛尼米', '当灰姑娘残忍的继母阻止她参加皇家舞会时，她得到了可爱的老鼠格斯和杰克以及她的仙女教母的意外帮助。', 'https://m.media-amazon.com/images/M/MV5BZWY3ZTM4YTUtZjg1OC00NjM2LTllMTItZjA4MGU0MzcwNjhkXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '艾琳·伍兹, 埃莉诺·奥德利, 弗娜·费尔顿, 克莱尔·杜·布雷, 罗达·威廉姆斯, 詹姆斯·麦克唐纳', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1025, '石中剑', '动画,儿童,奇幻,歌舞', 1963, '沃夫冈·雷瑟曼', '一个名叫亚瑟的贫穷男孩在巫师梅林的帮助下，学习爱、善良、知识和勇敢的力量。', 'https://m.media-amazon.com/images/M/MV5BN2U1ZDI3OGMtOTU0Ni00MTAxLTgwYWEtN2QwZDI4ZTQ5MTQ0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '塞巴斯蒂安·卡伯特, 卡尔·斯文森, 里基·索伦森, 朱尼厄斯·马修斯, 金妮·泰勒, 玛莎·温特沃斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1028, '欢乐满人间', '儿童,喜剧,奇幻,歌舞', 1964, '罗伯特·史蒂文森', '在世纪之交的伦敦，一位神奇的保姆利用音乐和冒险帮助两个被忽视的孩子与父亲更亲近。', 'https://m.media-amazon.com/images/M/MV5BNThiNjgzMTYtZjUzMC00YTVlLTg4MDItMmFjMDIwYjg4ZDAwXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '朱莉·安德鲁斯, 迪克·范·戴克, 大卫·汤姆林森, 格林尼斯·约翰斯, 赫敏·巴德利, 雷塔·肖', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1032, '爱丽丝梦游仙境', '冒险,动画,儿童,奇幻,歌舞', 1951, '克莱德·杰洛尼米', '爱丽丝偶然进入仙境。她能回家吗？如果红心皇后得逞，就不能。', 'https://m.media-amazon.com/images/M/MV5BMTgyMjM2NTAxMF5BMl5BanBnXkFtZTgwNjU1NDc2MTE@._V1_FMjpg_UX1000_.jpg', '凯瑟琳·博蒙特, 埃德·温, 理查德·海登, 斯特林·霍洛威, 杰里·科隆纳, 弗娜·费尔顿', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1035, '音乐之声', '歌舞,爱情', 1965, '罗伯特·怀斯', '在1930年代的奥地利，一位年轻的修女被她的修道院派去成为一名寡妇海军军官的七个孩子的家庭教师。', 'https://m.media-amazon.com/images/M/MV5BYWJhYmU4MjQtZDJhYi00ZGVjLTlkNTEtNzkzNGVjOWQ3MjcwXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '朱莉·安德鲁斯, 克里斯托弗·普卢默, 埃莉诺·帕克, 理查德·海登, 佩吉·伍德, 查米安·卡尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1036, '虎胆龙威', '动作,犯罪,惊悚', 1988, '约翰·麦克蒂尔南', '纽约警察约翰·麦克莱恩试图拯救他的分居妻子和其他几人，他们在洛杉矶纳卡托米广场摩天楼的圣诞夜派对上被恐怖分子劫持。', 'https://m.media-amazon.com/images/M/MV5BMGNlYmM1NmQtYWExMS00NmRjLTg5ZmEtMmYyYzJkMzljYWMxXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '布鲁斯·威利斯, 邦妮·比蒂丽娅, 雷金纳德·维尔约翰逊, 保罗·格莱森, 德沃雷奥克斯·怀特, 威廉·阿瑟顿', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1059, '罗密欧与朱丽叶', '剧情,爱情', 1996, '巴兹·鲁赫曼', '莎士比亚的著名戏剧被更新到维罗纳的现代郊区，同时保留其原始对话。', 'https://m.media-amazon.com/images/M/MV5BZjBhYjkxN2EtNDc1Yy00NTViLTkxMjQtMDYxMzM0MzA3NGQ4XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '莱昂纳多·迪卡普里奥, 克莱尔·丹尼斯, 约翰·雷吉扎莫, 哈罗德·佩里诺, 卢皮塔·奥乔亚, 皮特·波斯尔思韦特', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1073, '欢乐糖果屋', '儿童,喜剧,奇幻,歌舞', 1971, '梅尔·斯图尔特', '一个贫穷但充满希望的男孩寻找五张梦寐以求的金票之一，这将带他参观威利·旺卡的神秘巧克力工厂。', 'https://m.media-amazon.com/images/M/MV5BNzllNzlkNzYtZTEzZi00ODMwLWFlYTctZDE5Mzk0NTM1NmViXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '吉恩·怀尔德, 杰克·艾伯森, 彼得·奥斯图姆, 罗伊·金尼尔, 朱莉·唐·科尔, 伦纳德·斯通', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1079, '一条叫旺达的鱼', '喜剧,犯罪', 1988, '查尔斯·克莱顿', '在伦敦，四个非常不同的人联手进行珠宝抢劫，然后试图为了赃物而互相背叛。', 'https://m.media-amazon.com/images/M/MV5BNjFhZDg1ZmEtYmI0Ny00MjM3LWIxNzItMzU1MzczZTljMTkxXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '约翰·克立斯, 杰米·李·柯蒂斯, 凯文·克莱恩, 迈克尔·帕林, 玛丽亚·艾特肯, 汤姆·乔治森', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1080, '万世魔星', '喜剧', 1979, '特里·琼斯', '出生于原始圣诞节那天，与耶稣基督隔墙的马厩里，拿撒勒的布莱恩一生都被误认为是弥赛亚。', 'https://m.media-amazon.com/images/M/MV5BNDMzY2E4NjEtMTJiZC00Y2UzLWFiM2MtZWVhNTg5OGQxNjk1XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '格雷厄姆·查普曼, 约翰·克立斯, 特里·吉列姆, 埃里克·艾多尔, 特里·琼斯, 迈克尔·帕林', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1088, '辣身舞', '剧情,歌舞,爱情', 1987, '埃米尔·阿多利诺', '与家人在卡茨基尔度假村度过夏天时，弗朗西斯\"宝贝\"豪斯曼爱上了营地的舞蹈教练约翰尼·卡斯尔。', 'https://m.media-amazon.com/images/M/MV5BZmIwZjA1NzUtNTA0OS00OWMyLWE5MzctM2RjOWYxZjQyZDdmXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '詹妮弗·格雷, 帕特里克·斯威兹, 杰里·奥尔巴赫, 辛西娅·罗兹, 杰克·韦斯顿, 简·布鲁克', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1089, '落水狗', '犯罪,悬疑,惊悚', 1992, '昆汀·塔伦蒂诺', '当一次简单的珠宝抢劫变得糟糕透顶时，幸存的罪犯开始怀疑其中一人是警察线人。', 'https://m.media-amazon.com/images/M/MV5BMmMzYjg4NDctYWY0Mi00OGViLWIzMTMtYWNlZGY5ZDJmYjk3XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '哈维·凯特尔, 蒂姆·罗斯, 迈克尔·马德森, 克里斯·佩恩, 史蒂夫·布西密, 劳伦斯·蒂尔尼', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1090, '野战排', '剧情,战争', 1986, '奥利弗·斯通', '克里斯·泰勒是越南的一名新兵，他发现自己卷入两名中士的意志之战中，一人善良，一人邪恶。', 'https://m.media-amazon.com/images/M/MV5BZjE4YjllODAtZGMxZS00Mjg2LThkOWUtZjNkMjQ5YThiNDU4XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '基思·大卫, 福里斯特·惠特克, 弗朗西斯科·奎因, 凯文·狄龙, 约翰·C·麦金利, 雷吉·约翰逊', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1094, '哭泣游戏', '剧情,爱情,惊悚', 1992, '尼尔·乔丹', '一名被爱尔兰共和军绑架的英国士兵很快与其中一名绑架者成为朋友，后者随后被卷入士兵的世界。', 'https://m.media-amazon.com/images/M/MV5BY2NlZjJlODgtNDQ1ZC00YjcxLTgxMjAtODNmYmQ5MTRhOTNkXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '福里斯特·惠特克, 米兰达·理查森, 斯蒂芬·瑞, 阿德里安·邓巴, 布雷夫尼·麦肯纳, 乔·萨维诺', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1097, 'E.T.外星人', '儿童,剧情,科幻', 1982, '史蒂文·斯皮尔伯格', '一个 troubled 孩子鼓起勇气帮助一个友好的外星人逃离地球并返回他的家乡星球。', 'https://m.media-amazon.com/images/M/MV5BYTNhNmY0YWMtMTczYi00MTA0LThhMmUtMTIxYzE0Y2QwMzRlXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '迪·沃勒斯, 亨利·托马斯, 彼得·科约特, 罗伯特·麦克纳顿, 德鲁·巴里摩尔, K.C.马特尔', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1101, '壮志凌云', '动作,爱情', 1986, '托尼·斯科特', '顶级枪海军战斗机武器学校是精英中的精英训练精炼飞行技能的地方。当王牌战斗机飞行员麦德林被送到学校时，他鲁莽的态度和傲慢的举止使他与其他飞行员发生冲突。', 'https://m.media-amazon.com/images/M/MV5BZmVjNzQ3MjYtYTZiNC00Y2YzLWExZTEtMTM2ZDllNDI0MzgyXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '汤姆·克鲁斯, 凯莉·麦吉利斯, 瓦尔·基尔默, 安东尼·爱德华兹, 汤姆·斯凯里特, 迈克尔·艾恩塞德', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1124, '金色池塘', '剧情', 1981, '马克·雷戴尔', '脾气暴躁的诺曼与女儿切尔西疏远。然而，在金色池塘，他和妻子同意照顾切尔西新男友的儿子比利。', 'https://m.media-amazon.com/images/M/MV5BZmI3OGQ0YjQtZjNkYi00NmEzLWE5NjMtMTdkYjA4YTdiYzBiXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '凯瑟琳·赫本, 亨利·方达, 简·方达, 道格·麦基翁, 达布尼·科尔曼, 威廉·兰托', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1127, '深渊', '动作,冒险,科幻,惊悚', 1989, '詹姆斯·卡梅隆', '一支平民潜水队被招募寻找一艘失踪的核潜艇，并在遭遇一种外星水生物种时面临危险。', 'https://m.media-amazon.com/images/M/MV5BMGRkNzJlNjgtZmUwYS00Y2U3LTljZDctMTQxYWIxOWVjMzNjXkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '艾德·哈里斯, 玛丽·伊丽莎白·马斯特兰托尼奥, 迈克尔·比恩, 利奥·伯梅斯特, 托德·格拉夫, 约翰·贝德福德·劳埃德', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1136, '蒙提·派森和圣杯', '冒险,喜剧,奇幻', 1975, '特里·吉列姆', '亚瑟王和他的圆桌骑士们踏上一次超现实的、低成本的寻找圣杯之旅，遇到许多非常愚蠢的障碍。', 'https://m.media-amazon.com/images/M/MV5BYWY4YmUzZmUtMzQ0ZS00N2Y2LWJlODQtN2IwMDc1MWQwMmU3XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '格雷厄姆·查普曼, 约翰·克立斯, 埃里克·艾多尔, 特里·吉列姆, 特里·琼斯, 迈克尔·帕林', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1148, '超级无敌掌门狗：错误的裤子', '动画,儿童,喜剧,犯罪', 1993, '尼克·帕克', '格罗米特与一位神秘的企鹅寄宿生发生冲突，后者策划了一个涉及前NASA科技裤的邪恶计划。', 'https://m.media-amazon.com/images/M/MV5BZGI0ZjU1ZmUtZmRlZC00Yjg3LWI1MjktM2YwYmU1NGNiYzU0XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '彼得·萨利斯', '2025-11-24 12:30:37');
INSERT INTO `movies` VALUES (1172, '天堂电影院', '剧情', 1989, '朱塞佩·托纳多雷', '著名电影导演萨尔瓦多回到家乡参加当地剧院电影放映师阿尔弗雷多的葬礼。他回忆自己年轻时爱上电影的生活。', 'https://m.media-amazon.com/images/M/MV5BMTljNzc4YWEtYTZlMS00ODMyLWIwMTAtNWQxY2VkMDEwYTk5XkEyXkFqcGc@._V1_FMjpg_UX1000_.jpg', '安东内拉·阿蒂利, 恩佐·坎纳瓦莱, 伊萨·丹妮利, 利奥·古洛塔, 马可·莱奥纳尔迪, 普佩拉·马吉奥', '2025-11-24 12:30:37');
